code_template:
// This function has a bug — it should sum 1 through 5 (=15)
// but it returns something else. Add debug prints to find the bug.
fn buggy_sum() -> Int {
  var total = 0;
  var i = 0;
  while i < 5 {
    total += i;
    i += 1;
  }
  return total;
}

fn main() -> Int {
  let result = buggy_sum();
  return result;
}

solution:
fn debugged_sum() -> Int {
  var total = 0;
  var i = 1;
  while i <= 5 {
    io.println("Adding to total...");
    total += i;
    i += 1;
  }
  return total;
}

fn main() -> Int {
  let result = debugged_sum();
  return result;
}
